add_action( 'woocommerce_login_form_end', 'perfectpixel_login_redirect_previous_field' );

function perfectpixel_login_redirect_previous_field() {
	if ( ! empty( $_REQUEST['redirect_to'] ) ) {
		return; // An explicit redirect already exists.
	}
	$referer = wp_get_raw_referer();
	if ( ! $referer || ! wp_validate_redirect( $referer, false ) ) {
		return; // Only pages of this site.
	}
	$account = wc_get_page_permalink( 'myaccount' );
	if ( 0 === strpos( $referer, $account ) || false !== strpos( $referer, 'wp-login.php' ) ) {
		return;
	}
	echo '<input type="hidden" name="redirect" value="' . esc_url( $referer ) . '">';
}
